<?php /* i18n-ignore: inline PDF stylesheet is CSS, not prose. */ require_once __DIR__.'/helpers.php';?><!doctype html><html lang="<?=me(\App\Engine\Locale::getLocale())?>"><head><meta charset="utf-8"><style>body{font:11px DejaVu Sans;color:#202019;margin:30px}h1{font-size:25px}h2{font-size:16px}.brand{color:#b45d32}table{width:100%;border-collapse:collapse;margin-top:25px}td,th{padding:10px 5px;text-align:left;border-bottom:1px solid #ddd}small{color:#666}.totals{margin-top:25px;text-align:right}footer{margin-top:35px;font-size:9px;color:#666}tr{page-break-inside:avoid}.numeric{direction:ltr;unicode-bidi:embed;white-space:nowrap}</style></head><body><p class="brand"><?=me($settings['website_name'])?></p><h1><span><?=me(__('manor.quotation'))?></span></h1><p><?=me($quote['id'])?> · <span><?=me(__('manor.version'))?></span> <?=me($quote['version'])?></p><h2><?=me($record['unit_name'])?></h2><p><?=me($record['customer_name'])?><br><?=me($record['customer_email'])?></p><p><?=me(\App\Manor\Inventory::local($record['starts_at']))?> — <?=me(\App\Manor\Inventory::local($record['ends_at']))?> · Europe/London</p><p><span><?=me(__('manor.valid_until'))?></span> <?=me(\App\Manor\Inventory::local($quote['expires_at']))?></p><table><thead><tr><th><span><?=me(__('manor.item'))?></span></th><th><span><?=me(__('manor.qty'))?></span></th><th><span><?=me(__('manor.net'))?></span></th><th><span><?=me(__('manor.tax'))?></span></th></tr></thead><tbody><?php foreach($q['items'] as $item):if($quote['accepted_at']&&!$item['selected'])continue;?><tr><td><?=me($item['name'])?><br><small><?=me($item['description'])?> <?=me($item['refundable']?__('manor.refundable_deposit'):'')?></small></td><td><?=me($item['quantity'])?></td><td><span class="numeric"><?=pdf_money($item['net_pence'],$q['currency'])?></span></td><td><span class="numeric"><?=pdf_money($item['tax_pence'],$q['currency'])?></span></td></tr><?php endforeach?></tbody></table><div class="totals"><p><span><?=me(__('manor.service_charges'))?></span> <span class="numeric"><?=pdf_money($q['service_pence'],$q['currency'])?></span><br><span><?=me(__('manor.service_tax'))?></span> <span class="numeric"><?=pdf_money($q['tax_pence'],$q['currency'])?></span><br><span><?=me(__('manor.refundable_deposits'))?></span> <span class="numeric"><?=pdf_money($q['deposit_pence'],$q['currency'])?></span></p><h2><span><?=me(__('manor.total'))?></span> <span class="numeric"><?=pdf_money($q['total_pence'],$q['currency'])?></span></h2></div><h2><span><?=me(__('manor.terms'))?></span></h2><p><?=nl2br(me($q['terms']))?></p><?php if($quote['accepted_at']):?><p><span><?=me(__('manor.accepted'))?></span> <?=me($quote['accepted_at'])?> UTC</p><?php endif?><footer><?=me($settings['address'])?> · <?=me($settings['email'])?></footer></body></html>
